contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept an arbitrary depositor address (as bytes20 to avoid using tx.origin) and an amount to deposit.
    // The test contract will act as msg.sender for calls to c, so we only simulate a single actor: this contract.
    function run(address depositor, uint amount) public payable {
        // The test must act as if 'depositor' is this contract (since checker uses this contract as caller),
        // so require depositor == address(this) to ensure we are testing behavior for the caller that can interact.
        // This lets us observe credit via calling deposit/withdrawAll as this contract.
        require(depositor == address(this));

        // Ensure we have funds to deposit if amount > 0
        if (amount > 0) {
            require(address(this).balance >= amount);
            c.deposit{value: amount}();
        }

        // Observe before-values: contract balance and the test contract's balance.
        uint beforeContractBalance = address(c).balance;
        uint beforeSelfBalance = address(this).balance;

        // Also read credit via the public mapping getter
        uint beforeCredit = c.credit(address(this));

        // Make the deciding call and capture whether it reverted.
        bool reverted = false;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterContractBalance = address(c).balance;
        uint afterSelfBalance = address(this).balance;
        uint afterCredit = c.credit(address(this));

        // General rule:
        // If withdrawAll reverted, the contract balance and credit for this address must be unchanged.
        // If it did not revert, then afterCredit must be zero and the contract's balance must have decreased by exactly the original credit amount (and this contract's balance increased by that amount).
        assert(
            reverted
            ? (afterContractBalance == beforeContractBalance && afterCredit == beforeCredit)
            : (afterCredit == 0 && afterContractBalance + beforeCredit == beforeContractBalance)
        );
    }

    // Allow receiving Ether when c sends funds back to this contract
    receive() external payable {}
}

