contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function: params are deposit amount and a flag telling whether to attempt withdraw
    function run(uint depositAmount, bool callWithdraw) public payable {
        require(address(this).balance >= depositAmount);

        // record contract C balance before any interaction
        uint before = address(c).balance;

        // perform a deposit of depositAmount
        c.deposit{value: depositAmount}();

        // record balance after deposit
        uint afterDeposit = address(c).balance;

        // afterDeposit should be before + depositAmount
        // callWithdraw may trigger withdrawAll; capture whether it reverts
        bool withdrewReverted = false;
        if (callWithdraw) {
            try c.withdrawAll() {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        }

        uint after = address(c).balance;

        // amount that left C (observable) is delta = afterDeposit - after
        uint delta;
        if (afterDeposit >= after) {
            delta = afterDeposit - after;
        } else {
            // should not happen: C balance increased after withdraw attempt
            delta = 0;
        }

        // General invariant to assert:
        // 1) afterDeposit == before + depositAmount (deposit always increases C balance by depositAmount)
        // 2) if withdraw was called and it did not revert, then delta == depositAmount (C sent out the deposited amount)
        // 3) if withdraw was called and it reverted, then delta == 0 (no Ether left C)
        assert(
            afterDeposit == before + depositAmount
            && (
                !callWithdraw || (!withdrewReverted && delta == depositAmount) || (withdrewReverted && delta == 0)
            )
        );
    }

    // allow receiving Ether in case withdrawAll sends funds here
    receive() external payable {}
}

